const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const RUNS = STATE + '/humanizer_runs';
const LOGD = '/home/node/.n8n/logs';
const SCORES = STATE + '/humanizer_scores.jsonl';
// the daily Pangram credit counter is shared with the moderation
// warn-gate (issue #76): both consumers draw on the same free-tier
// account, so the eval path charges into the same file under the
// same 'pangram-credits' lock instead of keeping a second estimate
// that could silently double-spend the allowance
const PANGRAM_CREDITS = STATE + '/pangram_credits.json';
// hands-agent task queue (the host's hands-agent/queue bind mount,
// same root the pangram warn-gate and the habr driver enqueue into).
// The dirs must already exist - a missing mount must NEVER be
// created here: the pangram scorer falls back to stub instead.
const HANDS_QUEUE = '/home/node/hands-queue';
// fixture corpus root: <tier>/<lang>.txt cells with an optional
// <lang>.spans.json annotation sibling. Read-only mount in
// production; HUMANIZER_FIXTURES overrides the path for eval volume
// layouts and for the check_humanizer harness.
const FIXTURES = ENV('HUMANIZER_FIXTURES') || '/home/node/fixtures/humanizer';
// the fixtures mount and the hands-queue dirs are deliberately NOT
// in the mkdir list: both are external mounts whose absence is a
// skip condition, not a state dir to create
// SYNC-BEGIN: mkdir-collect
const mkdirErrs = [];
for (const d of [LOGD, STATE, RUNS]) {
  try {
    fs.mkdirSync(d, { recursive: true });
  } catch (e) {
    mkdirErrs.push({ dir: d,
      error: String((e && e.message) || e).slice(0, 150) });
  }
}
// SYNC-END: mkdir-collect
// best-effort by contract: a transient FS failure must NEVER
// propagate out of log() - a logging crash must not kill the tick,
// same discipline the sibling nodes keep
const log = (rec) => {
  try {
    fs.appendFileSync(LOGD + '/humanizer-eval.jsonl',
      JSON.stringify({ ts: new Date().toISOString(), ...rec }) + '\n');
  } catch (e) {}
};
for (const m of mkdirErrs) {
  try { log({ action: 'mkdir-failed', dir: m.dir, error: m.error }); }
  catch (e) {}
}
// same tmp+rename write discipline as the sibling Code nodes: a crash
// mid-writeFileSync leaves a torn JSON.
// SYNC: sibling copies live in Handle TG Update, Prepare Draft,
// Compose Message and Handle Pangram Results (sp-tg-moderation),
// Generate Drafts (sp-content-gen), Resolve Chat + Webhook
// (sp-tg-setup), Analytics Tick (sp-analytics) - Publish Tick
// carries the hardened 0o600 variant. n8n Code nodes cannot share a
// prelude - replicate any fix to every copy by hand.
// SYNC-BEGIN: write-json-atomic
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) +
    Math.random().toString(36).slice(2, 6);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2));
  fs.renameSync(tmp, p);
};
// SYNC-END: write-json-atomic

// withLock serializes run-record and credit-counter mutations under
// tokened state/locks/<key>.lock files - the same contract the
// pangram warn-gate uses against overlapping poll executions:
// EEXIST = live lock = LockBusyError (.lockBusy), expired/unreadable
// locks are stolen via tmp+rename and proven by re-read, release
// unlinks only our own token.
// SYNC: identical copies live in Handle TG Update, Prepare Draft and
// Handle Pangram Results (sp-tg-moderation) and Publish Tick
// (sp-publish). n8n Code nodes cannot share a prelude - replicate
// any fix to every copy by hand.
// SYNC-BEGIN: file-lock
const LOCKS_DIR = STATE + '/locks';
try { fs.mkdirSync(LOCKS_DIR, { recursive: true }); } catch (e) {}
const lockBusyError = () => {
  const e = new Error('state lock busy');
  e.name = 'LockBusyError';
  e.lockBusy = true;
  return e;
};
const withLock = (key, ttlMs, fn) => {
  const lp = LOCKS_DIR + '/' + key + '.lock';
  // no crypto/process in Code nodes - timestamp+random like the
  // writeJsonAtomic tmp names is entropy enough for a lock token
  const mine = Date.now().toString(36) + '-' +
    Math.random().toString(36).slice(2, 10);
  const claim = JSON.stringify({ token: mine, exp: Date.now() + ttlMs });
  let held = false;
  try {
    fs.writeFileSync(lp, claim, { flag: 'wx', mode: 0o600 });
    held = true;
  } catch (e) {
    if (!e || e.code !== 'EEXIST') throw e;
    // only a PROVEN-live lock (readable, exp in the future) makes us
    // busy - anything else is stolen, then verified by re-read
    // because a competing stealer may have won the rename
    let cur = null;
    try { cur = JSON.parse(fs.readFileSync(lp, 'utf8')); } catch (e2) {}
    if (cur && Number.isFinite(Number(cur.exp)) &&
        Date.now() <= Number(cur.exp)) {
      throw lockBusyError();
    }
    const tmp = lp + '.tmp-' + mine;
    try {
      fs.writeFileSync(tmp, claim, { mode: 0o600 });
      fs.renameSync(tmp, lp);
      held = JSON.parse(fs.readFileSync(lp, 'utf8')).token === mine;
    } catch (e3) { held = false; }
    try { fs.unlinkSync(tmp); } catch (e4) {}
    if (!held) throw lockBusyError();
  }
  try {
    return fn();
  } finally {
    if (held) {
      try {
        const cur = JSON.parse(fs.readFileSync(lp, 'utf8'));
        if (cur && cur.token === mine) fs.unlinkSync(lp);
      } catch (e5) {
        // release failures never propagate: a leaked lock expires
        // on its own; ENOENT just means it was already removed
        if (!e5 || e5.code !== 'ENOENT') {
          try {
            if (typeof log === 'function') {
              log({ action: 'lock-release-failed', key: key,
                error: String(e5).slice(0, 120) });
            }
          } catch (e6) {}
        }
      }
    }
  }
};
// SYNC-END: file-lock

// ------------------------------------------------------------------
// eval config (issue #78): every knob is env-overridable, with the
// same 'explicit 0 means 0' parse discipline the pangram gate uses
const SCORER_RAW =
  String(ENV('HUMANIZER_SCORER') || 'stub').trim().toLowerCase();
// exact-token gate: 'stub' (default) and 'pangram' are the only live
// values; anything else fails to stub so a typo can never silently
// burn real detector credits
const SCORER = SCORER_RAW === 'pangram' ? 'pangram' : 'stub';
if (SCORER_RAW !== 'stub' && SCORER_RAW !== 'pangram') {
  try {
    log({ action: 'humanizer-scorer-unknown',
      value: SCORER_RAW.slice(0, 40) });
  } catch (e) {}
}
const PARTNER_RAW =
  String(ENV('HUMANIZER_PARTNER') || 'stub').trim().toLowerCase();
const PARTNER = PARTNER_RAW === 'inhouse' ? 'inhouse' : 'stub';
if (PARTNER_RAW !== 'stub' && PARTNER_RAW !== 'inhouse') {
  try {
    log({ action: 'humanizer-partner-unknown',
      value: PARTNER_RAW.slice(0, 40) });
  } catch (e) {}
}
// ai_score below the threshold = pass; on/above = rewrite or
// escalate. Clamped to the score's 0-100 domain: an out-of-range
// env value would either auto-pass everything (<0) or escalate
// everything (>100), and both failures look like a working eval
const THRESHOLD = (() => {
  const n = Number.parseInt(
    String(ENV('HUMANIZER_THRESHOLD') || '').trim(), 10);
  return Number.isFinite(n) ? Math.min(100, Math.max(0, n)) : 50;
})();
// rewrite-attempt cap before the run escalates best-so-far
const MAX_ITERS = (() => {
  const n = Number.parseInt(
    String(ENV('HUMANIZER_MAX_ITERS') || '').trim(), 10);
  return Number.isFinite(n) && n > 0 ? n : 2;
})();
// shared Pangram daily spend ceiling for THIS consumer, default 20 -
// an explicit '0' means ZERO (empty/unset/non-numeric falls back to
// 20; a '|| 20' fallback would wrongly turn a real 0 into the
// default). Charged optimistically at enqueue, ceil(words/100).
const HUMANIZER_DAILY = (() => {
  const raw = String(ENV('HUMANIZER_DAILY_CREDITS') || '').trim();
  if (!raw) return 20;
  const n = Number.parseInt(raw, 10);
  return Number.isFinite(n) ? Math.max(0, n) : 20;
})();
// a rescore must beat the best-so-far by more than this margin to
// count as a regression - absorbs the stub jitter band so an
// equivalent rewrite never false-reverts
const REGRESS_MARGIN = 10;
// llm-gateway /run endpoint for the inhouse partner stage
const GATEWAY =
  String(ENV('LLM_GATEWAY_URL') || 'http://llm-gateway:8787')
    .replace(/\/+$/, '');
// enabled chains: comma list; 'baseline' = score-only (no rewrite
// stages), 'editor' = [inhouse/stub editor], anything else is a
// '+'-separated ordered stage list (e.g. 'writehuman+editor')
const CHAINS = String(ENV('HUMANIZER_CHAINS') || 'baseline,editor');
// Pangram's own reliability floor, same value the warn-gate uses
const PANGRAM_MIN_WORDS = 150;
// a rewrite claim older than this is treated as a crashed tick and
// may be re-claimed - mirrors the stale-claim discipline Publish
// Tick uses on processing/ files
const REWRITE_STALE_MS = 600000;
// same window for a scorer_pending claim: a pangram task with no
// landed artifact after ~10min is a dead claim (worker crashed,
// queue mount flapped, or the result was consumed by a tick that
// died before its run write). The stale claim gets ONE re-enqueue
// attempt; a second stale lands on scorer_failed for a human
const SCORE_STALE_MS = 600000;
const TRACE_CAP = 200;

const wordsOf = (t) =>
  String(t || '').split(/\s+/).filter(Boolean).length;
const today = () => new Date().toISOString().slice(0, 10);
const cap = (s, n) => Array.from(String(s)).slice(0, n).join('');
// FNV-1a - the same non-crypto hash the sibling nodes use; here it
// feeds the deterministic stub-score jitter
const fnvNum = (s) => {
  let h = 0x811c9dc5;
  s = String(s || '');
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h;
};

// run record io ------------------------------------------------------------
const runPath = (id) => RUNS + '/' + id + '.json';
const loadRun = (id) => {
  try {
    return JSON.parse(fs.readFileSync(runPath(id), 'utf8'));
  } catch (e) { return null; }
};
// re-read-then-mutate under the caller's lock - same shape as the
// sibling updateDraft guarded-write contract
const updateRun = (id, mutate, guard) => {
  const cur = loadRun(id);
  if (!cur) return null;
  if (guard && !guard(cur)) return null;
  mutate(cur);
  cur.updated_at = new Date().toISOString();
  writeJsonAtomic(runPath(id), cur);
  return cur;
};
const trace = (run, action, detail) => {
  if (!Array.isArray(run.trace)) run.trace = [];
  run.trace.push({ at: new Date().toISOString(), action: action,
    ...(detail || {}) });
  if (run.trace.length > TRACE_CAP) {
    run.trace = run.trace.slice(-TRACE_CAP);
  }
};
// append-only score ledger: one single-line JSON record per scored
// cell under the scores lock - O_APPEND keeps a <PIPE_BUF line
// atomic across writers, same discipline as the registry event
// stream
const appendScoreRow = (row) => {
  try {
    withLock('humanizer-scores', 15000, () => {
      fs.appendFileSync(SCORES, JSON.stringify(row) + '\n');
    });
  } catch (e) {
    try {
      log({ action: 'score-append-failed',
        error: String((e && e.message) || e).slice(0, 150) });
    } catch (e2) {}
  }
};

// stub scorer --------------------------------------------------------------
// Deterministic fake detector (SCORER=stub, the default): counts
// known AI-marker phrases - filler openers/connectors the partner
// stub knows how to strip (STUB_STRIPPABLE) plus jargon words it can
// only flag (STUB_JARGON) - adds a sentence-uniformity penalty for
// metronome-even paragraphs, plus a small FNV jitter keyed on
// text+iteration so a rewrite measurably moves the score while the
// same (text, iteration) pair always scores identically. Pure
// function - no randomness, no network.
const STUB_STRIPPABLE = [
  "in today's fast-paced world",
  'it is important to note',
  'it is worth noting',
  'it is worth mentioning',
  'it goes without saying',
  'needless to say',
  'that being said',
  'in conclusion',
  'furthermore',
  'moreover',
  'additionally',
  // RU filler (kept as escapes so this file stays ASCII)
  '\u0432\u0430\u0436\u043d\u043e \u043e\u0442\u043c\u0435\u0442\u0438\u0442\u044c',
  '\u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u043e\u0442\u043c\u0435\u0442\u0438\u0442\u044c',
  '\u0441\u0442\u043e\u0438\u0442 \u043e\u0442\u043c\u0435\u0442\u0438\u0442\u044c',
  '\u0432 \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u043c \u043c\u0438\u0440\u0435',
  '\u0432 \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u043c \u0431\u044b\u0441\u0442\u0440\u043e \u043c\u0435\u043d\u044f\u044e\u0449\u0435\u043c\u0441\u044f \u043c\u0438\u0440\u0435',
  '\u043a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e',
  '\u0442\u0430\u043a\u0438\u043c \u043e\u0431\u0440\u0430\u0437\u043e\u043c',
  '\u0432 \u0437\u0430\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435',
  '\u043d\u0435 \u0441\u0435\u043a\u0440\u0435\u0442'
];
const STUB_JARGON = [
  'delve', 'leverage', 'seamless', 'cutting-edge', 'game-changer',
  'robust', 'innovative', 'elevate', 'unlock', 'landscape', 'realm',
  'tapestry', 'testament', 'streamline', 'synergy', 'holistic',
  'ever-evolving', 'paradigm', 'multifaceted', 'utilize',
  // RU jargon stems
  '\u0431\u0435\u0441\u0448\u043e\u0432\u043d', '\u0440\u0435\u0432\u043e\u043b\u044e\u0446\u0438\u043e\u043d\u043d', '\u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d', '\u0438\u043d\u043d\u043e\u0432\u0430\u0446\u0438\u043e\u043d\u043d', '\u043f\u0435\u0440\u0435\u0434\u043e\u0432',
  '\u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d', '\u0433\u043e\u0431\u0435\u043b\u0435\u043d', '\u043f\u043e\u0433\u0440\u0443\u0437'
];
// returns the flagged phrases themselves, not just a count - the
// same list is what detector_payload.marker_spans forwards to the
// partner ({text, marker_type, reason}), matching the
// fixtures' <lang>.spans.json annotation shape
const markerSpans = (text) => {
  const lower = ' ' + String(text || '').toLowerCase() + ' ';
  const spans = [];
  for (const p of STUB_STRIPPABLE) {
    if (lower.indexOf(p) >= 0) {
      spans.push({ text: p, marker_type: 'filler',
        reason: 'strippable filler phrase' });
    }
  }
  for (const p of STUB_JARGON) {
    if (lower.indexOf(p) >= 0) {
      spans.push({ text: p, marker_type: 'jargon',
        reason: 'AI-jargon stem the partner can only flag' });
    }
  }
  return spans;
};
// uniformity penalty: metronome-even sentence lengths are the most
// reliable slop tell the fixtures exercise
const uniformPenalty = (text) => {
  const lens = String(text || '').split(/[.!?\u2026\n]+/)
    .map((s) => s.split(/\s+/).filter(Boolean).length)
    .filter((n) => n > 0);
  if (lens.length < 3) return 0;
  const spread = Math.max(...lens) - Math.min(...lens);
  if (spread <= 3) return 20;
  if (spread <= 6) return 8;
  return 0;
};
const stubScore = (text, iteration) => {
  const spans = markerSpans(text);
  const hits = spans.length;
  const pen = uniformPenalty(text);
  const jit = fnvNum(String(text) + '|' + Number(iteration || 0)) % 8;
  const score = Math.max(5, Math.min(97, 12 + 20 * hits + pen + jit));
  const label = score >= 75 ? 'AI Generated'
    : score >= 45 ? 'Possibly AI' : 'Possibly human';
  return { score: score, label: label, confidence: score,
    via: 'stub', hits: hits, uniform_penalty: pen,
    // the contract the partner reads: which phrases the scorer
    // penalized, in the same {text, marker_type, reason} shape the
    // fixture spans.json annotations use
    marker_spans: spans,
    words: wordsOf(text), at: new Date().toISOString() };
};
// stub partner: ONE deterministic edit per call - strip the earliest
// strippable filler phrase, else split the longest sentence at a
// comma so a jargon-flagged text still gets a measurable (but
// score-neutral) restructure. Single-edit-per-call is deliberate: it
// makes multi-iteration runs exercise the real loop instead of
// converging in one shot
const stubPartner = (text) => {
  const src = String(text || '');
  const lower = src.toLowerCase();
  let best = -1;
  let phrase = null;
  for (const p of STUB_STRIPPABLE) {
    const i = lower.indexOf(p);
    if (i >= 0 && (best < 0 || i < best)) { best = i; phrase = p; }
  }
  if (phrase !== null) {
    let out = src.slice(0, best) + src.slice(best + phrase.length);
    out = out
      .replace(/\s*,\s*,\s*/g, ', ')
      .replace(/,\s*\./g, '.')
      .replace(/\(\s*\)/g, '')
      .replace(/\s+([,.;:!?])/g, '$1')
      .replace(/^[,.;:\s]+/, '')
      .replace(/ {2,}/g, ' ')
      .trim();
    // a sentence-initial strip can leave a lowercase start
    out = out.charAt(0).toUpperCase() + out.slice(1);
    out = out.replace(/([.!?]\s+)([a-z\u0430-\u044f\u0451])/g,
      (m, p1, p2) => p1 + p2.toUpperCase());
    return { ok: true, rewritten_text: out,
      edits: [{ span_original: phrase, span_new: '',
        reason: 'filler phrase removed' }] };
  }
  // fallback: split the longest sentence at its earliest comma so
  // the rescore sees a different (but marker-identical) text
  const sentences = src.split(/(?<=[.!?])\s+/);
  let li = -1;
  let lw = 0;
  for (let i = 0; i < sentences.length; i++) {
    const w = sentences[i].split(/\s+/).filter(Boolean).length;
    if (w > lw) { lw = w; li = i; }
  }
  if (li >= 0 && lw >= 8) {
    const s = sentences[li];
    const ci = s.indexOf(', ');
    if (ci > 0) {
      const repl = s.slice(0, ci) + '. ' +
        s.charAt(ci + 2).toUpperCase() + s.slice(ci + 3);
      const out = sentences.slice(0, li).concat([repl])
        .concat(sentences.slice(li + 1)).join(' ');
      return { ok: true, rewritten_text: out,
        edits: [{ span_original: cap(s, 60), span_new: cap(repl, 60),
          reason: 'long sentence split at clause boundary' }] };
    }
  }
  return { ok: true, rewritten_text: src,
    edits: [{ span_original: '', span_new: '',
      reason: 'no strippable marker or splittable sentence' }] };
};

// pangram scorer -----------------------------------------------------------
// same counter conventions as the moderation warn-gate
// (state/pangram_credits.json {date, est_spent, last_seen_left}):
// est_spent resets on UTC date change, charged optimistically at
// enqueue ceil(words/100)
const loadCredits = () => {
  let c = null;
  try {
    c = JSON.parse(fs.readFileSync(PANGRAM_CREDITS, 'utf8'));
  } catch (e) {}
  if (!c || typeof c !== 'object') c = {};
  if (c.date !== today()) {
    c.date = today();
    c.est_spent = 0;
    // the per-task charge ledger resets with the daily counter -
    // entries are only read for same-day idempotent re-arms
    c.charged = {};
  }
  c.est_spent = Number(c.est_spent) || 0;
  if (!Number.isFinite(Number(c.last_seen_left))) {
    c.last_seen_left = null;
  }
  return c;
};
const listDir = (d) => {
  try { return fs.readdirSync(d); } catch (e) { return null; }
};
const consume = (p) => {
  try { fs.renameSync(p, p + '.consumed'); } catch (e) {}
};
// map a pangram_check result onto the 0-100 ai_score the decide
// stage compares against THRESHOLD: a confident 'AI Generated' reads
// as its confidence; 'Possibly human' inverts (95% human = 5% AI)
const pangramScoreOf = (res) => {
  const m = /(\d{1,3})\s*%/.exec(
    String((res && (res.confidence || res.conf)) || ''));
  const conf = m ? Number(m[1]) : null;
  let label = null;
  if (res && (res.hit_aig || res.label === 'AI Generated')) {
    label = 'AI Generated';
  } else if (res && (res.hit_pai || res.label === 'Possibly AI')) {
    label = 'Possibly AI';
  } else if (res && (res.hit_ph || res.label === 'Possibly human')) {
    label = 'Possibly human';
  }
  if (!label || conf === null) return null;
  const score = label === 'Possibly human' ? 100 - conf : conf;
  return { score: score, label: label, confidence: conf };
};

// partner / stage call -----------------------------------------------------
const http = (o) => this.helpers.httpRequest(o);
// 'editor' is the inhouse humanizer-partner stage (or the stub
// transform under PARTNER=stub); every other declared stage name is
// an external humanizer resolved from HUMANIZER_EXT_<NAME>_URL -
// unset env means 'unavailable', never a fake call
const callStage = async (stage, run) => {
  if (stage === 'editor') {
    if (PARTNER === 'stub') {
      return stubPartner(run.working_text);
    }
    // detector_payload is the CONTRACTED view of the scorer's
    // findings - {ai_score, marker_spans:[{text, marker_type,
    // reason}]} - never the raw last_score blob: backend-specific
    // fields (via/hits/task/uniform_penalty) must not leak into a
    // role input the prompt documents against the public shape
    const last = run.last_score || {};
    const payload = {
      source_text: run.working_text,
      language: run.lang,
      detector_payload: {
        ai_score: Number.isFinite(Number(last.score))
          ? Number(last.score) : null,
        marker_spans: Array.isArray(last.marker_spans)
          ? last.marker_spans : []
      },
      iteration: run.iteration,
      previous_attempts: run.previous_attempts || [],
      protected_terms: run.protected_terms || [],
      persona_context: run.persona_context || '',
      mode: run.mode || 'rewrite'
    };
    try {
      const res = await http({
        method: 'POST',
        url: GATEWAY + '/run',
        body: {
          role: 'humanizer-partner',
          input: JSON.stringify(payload)
        },
        json: true,
        // explicit timeout like the sibling tg() helpers: an
        // unbounded request that hangs would stall the whole eval
        // tick behind one run
        timeout: 60000
      });
      const j = res && res.json;
      if (!j || typeof j.rewritten_text !== 'string' ||
          !j.rewritten_text.trim()) {
        return { ok: false,
          error: 'partner returned no rewritten_text' };
      }
      return { ok: true, rewritten_text: j.rewritten_text,
        edits: Array.isArray(j.edits) ? j.edits : [] };
    } catch (e) {
      // 422 (non-JSON or schema rejection) lands here with every
      // other transport fault - recorded as a failed attempt by the
      // caller, never retried inside the same tick
      const status = (e && (e.statusCode || (e.response &&
        e.response.statusCode))) || null;
      return { ok: false,
        error: 'partner http' + (status ? ' ' + status : '') + ': ' +
          String((e && e.message) || e).slice(0, 180) };
    }
  }
  // external humanizer stages: writehuman / stealthgpt / any other
  // declared name resolves only from its env URL - a declared stage
  // with no configured endpoint is 'unavailable' by contract
  const envName = 'HUMANIZER_EXT_' +
    String(stage).toUpperCase().replace(/[^A-Z0-9]+/g, '_') + '_URL';
  const url = String(ENV(envName) || '').trim();
  if (!url) return { ok: false, unavailable: true, env: envName };
  // TODO(issue #78): per-service request/response shapes still need
  // finalizing against the real writehuman/stealthgpt APIs; the
  // generic contract below is the extension point, not a stub - it
  // runs only when an operator configures the endpoint
  try {
    const res = await http({
      method: 'POST',
      url: url,
      body: {
        text: run.working_text,
        language: run.lang,
        iteration: run.iteration
      },
      json: true,
      timeout: 60000
    });
    const out = res && (res.rewritten_text || res.text ||
      (res.json && res.json.rewritten_text));
    if (typeof out !== 'string' || !out.trim()) {
      return { ok: false, error: 'external stage bad response' };
    }
    return { ok: true, rewritten_text: out,
      edits: [{ span_original: '', span_new: '',
        reason: 'rewritten by ' + stage }] };
  } catch (e) {
    return { ok: false,
      error: 'external http: ' +
        String((e && e.message) || e).slice(0, 180) };
  }
};

// run transitions ----------------------------------------------------------
const cellStage = (run) => run.cell_stage || 'input';
const recordScore = (run, s) => {
  run.last_score = s;
  appendScoreRow({
    run_id: run.run_id,
    fixture: run.fixture,
    chain: run.chain,
    stage: cellStage(run),
    score_label: s.label,
    confidence: s.confidence,
    // the scorer backend that produced this row - regression and
    // best-so-far comparisons are only valid inside one backend, so
    // the ledger stamps it per row instead of mixing scales silently
    scorer_backend: s.via || 'none',
    words: s.words,
    credits_used: run.credits_used,
    at: new Date().toISOString()
  });
};
// escalation 'TG card' stub (issue #78): the operator-facing card is
// a later production decision - for eval the escalated record itself
// carries the best-so-far text + score and a trace tail, plus one
// ledger line, so nothing a human would need is lost
const escalateRun = (run, reason, detail) => {
  run.state = 'escalated';
  run.outcome = reason;
  // one ledger line per escalation - the stub 'TG card' trail
  try {
    log({ run: run.run_id, fixture: run.fixture, chain: run.chain,
      action: 'humanizer-escalate', reason: reason,
      iterations: run.iteration,
      best_score: run.best ? run.best.score : null });
  } catch (e) {}
  run.escalation = {
    reason: reason,
    best_text: run.best ? run.best.text : run.working_text,
    best_score: run.best ? run.best.score : null,
    best_stage: run.best ? run.best.stage : null,
    trace_tail: (run.trace || []).slice(-10),
    at: new Date().toISOString(),
    ...(detail || {})
  };
};
const doneRun = (run, outcome) => {
  run.state = 'done';
  run.outcome = outcome;
};

// decide stage (inside the run lock): the order is the issue #78
// contract - pass, iteration cap, regression, otherwise rewrite
const decideStep = (run) => {
  const cur = run.last_score;
  if (!cur || !Number.isFinite(Number(cur.score))) {
    trace(run, 'escalate', { reason: 'no_score' });
    escalateRun(run, 'no_score');
    return 'escalated';
  }
  const score = Number(cur.score);
  const curBackend = cur.via || 'unknown';
  // scores from different scorer backends live on different scales -
  // a mid-run backend switch (e.g. pangram -> stub fallback) makes
  // the recorded best incomparable, so it is dropped and this score
  // starts a FRESH baseline rather than mixing scales in a
  // regression/best comparison. The reset is noted in the trace.
  // A best recorded without a backend tag (pre-contract runs) stays
  // comparable - there is nothing to prove it crossed backends
  if (run.best && run.best.backend && run.best.backend !== curBackend) {
    trace(run, 'best-reset-backend', { from: run.best.backend,
      to: curBackend });
    run.best = null;
  }
  const regressed = !!(run.best && Number.isFinite(Number(run.best.score)) &&
    score > Number(run.best.score) + REGRESS_MARGIN);
  if (!run.best || score < Number(run.best.score)) {
    run.best = { text: run.working_text, score: score,
      stage: cellStage(run), backend: curBackend,
      at: new Date().toISOString() };
  }
  if (score < THRESHOLD) {
    trace(run, 'pass', { score: score, threshold: THRESHOLD });
    doneRun(run, 'pass');
    return 'done';
  }
  if (run.iteration >= MAX_ITERS) {
    trace(run, 'escalate', { reason: 'max_iterations',
      iterations: run.iteration, score: score });
    escalateRun(run, 'max_iterations');
    return 'escalated';
  }
  if (regressed) {
    trace(run, 'revert', { score: score,
      best: run.best && run.best.score });
    run.working_text = run.best.text;
    doneRun(run, 'reverted');
    return 'done';
  }
  if (!run.stages || run.stages.length === 0) {
    trace(run, 'escalate', { reason: 'no_rewrite_stage',
      score: score });
    escalateRun(run, 'no_rewrite_stage');
    return 'escalated';
  }
  const stage = run.stages[run.iteration % run.stages.length];
  run.previous_attempts = (run.previous_attempts || [])
    .concat([{ iteration: run.iteration, stage: stage,
      score: score, label: cur.label,
      summary: 'ai_score ' + score + ' still >= ' + THRESHOLD }])
    .slice(-10);
  trace(run, 'rewrite-request', { stage: stage, score: score,
    iteration: run.iteration });
  run.state = 'rewriting';
  return 'rewriting';
};

// scoring/rescoring stage (inside the run lock): stub is fully
// synchronous; pangram either arms a pending task or consumes a
// landed result
const scoreStep = (run, id) => {
  if (SCORER !== 'pangram' || run.scorer_fallback) {
    const s = stubScore(run.working_text, run.iteration);
    recordScore(run, s);
    trace(run, 'score', { via: 'stub', score: s.score,
      label: s.label, stage: cellStage(run) });
    run.state = 'decide';
    return 'scored-stub';
  }
  // pangram mode: a pending task is owned by the result poll below
  const pend = run.scorer_pending;
  if (pend && pend.task) {
    const tid = pend.task;
    let landed = false;
    for (const dir of ['done', 'failed']) {
      const rp = HANDS_QUEUE + '/' + dir + '/' + tid + '.result.json';
      const tp = HANDS_QUEUE + '/' + dir + '/' + tid + '.json';
      const hasRes = fs.existsSync(rp);
      const hasTask = fs.existsSync(tp);
      // crash-after-consume window: a tick that renamed the landed
      // artifacts to *.consumed but died before its own run write
      // leaves the pending claim behind with only the .consumed
      // records - re-reading them finishes the consume instead of
      // waiting out SCORE_STALE_MS and re-charging a fresh task
      const resConsumed = !hasRes && fs.existsSync(rp + '.consumed');
      const taskConsumed = !hasTask && fs.existsSync(tp + '.consumed');
      if (!hasRes && !hasTask && !resConsumed && !taskConsumed) {
        continue;
      }
      landed = true;
      let res = null;
      let resBad = null;
      if (hasRes || resConsumed) {
        try {
          res = JSON.parse(fs.readFileSync(
            hasRes ? rp : rp + '.consumed', 'utf8'));
        } catch (e) { resBad = e; }
        if (resConsumed) {
          trace(run, 'score-recovered-consumed', { task: tid });
        }
      } else if (dir === 'done') {
        // task file in done/ with no result record: the recipe ran
        // but the verdict was never written - inconclusive, same
        // classification the warn-gate gives it
        res = { ok: true };
      }
      const failed = dir === 'failed' || resBad || !res ||
        res.ok === false;
      consume(rp);
      if (fs.existsSync(tp)) consume(tp);
      delete run.scorer_pending;
      const ps = failed ? null : pangramScoreOf(res);
      if (failed) {
        trace(run, 'escalate', { reason: 'scorer_failed',
          task: tid, error: cap(String(
            (resBad && resBad.message) ||
            (res && (res.error || res.err)) ||
            'recipe task failed without a result record'), 150) });
        escalateRun(run, 'scorer_failed', { task: tid });
        return 'escalated';
      }
      if (!ps) {
        trace(run, 'escalate', { reason: 'scorer_inconclusive',
          task: tid });
        escalateRun(run, 'scorer_inconclusive', { task: tid });
        return 'escalated';
      }
      const s = { score: ps.score, label: ps.label,
        confidence: ps.confidence, via: 'pangram', task: tid,
        // the pangram_check recipe only returns label + confidence
        // (hands-agent/recipes/pangram_check.yaml) - there is no
        // span-level Pangram data to forward, so the partner's
        // detector_payload gets an honest empty marker list
        marker_spans: [],
        words: pend.words, at: new Date().toISOString() };
      recordScore(run, s);
      trace(run, 'score', { via: 'pangram', score: ps.score,
        label: ps.label, task: tid, stage: cellStage(run) });
      run.state = 'decide';
      return 'scored-pangram';
    }
    if (!landed) {
      // no landed artifact yet: still in flight while the claim is
      // fresh; past SCORE_STALE_MS it is a dead claim - the inbox
      // copy is retracted if the worker never picked it up and the
      // run gets ONE re-enqueue attempt (scorer_retries), a second
      // stale lands on scorer_failed for a human
      const at = Date.parse(pend.at || '');
      const stale = !Number.isFinite(at) ||
        Date.now() - at > SCORE_STALE_MS;
      if (!stale) {
        trace(run, 'score-pending', { task: tid });
        return 'pending';
      }
      const retries = Number(run.scorer_retries || 0);
      if (retries >= 1) {
        // second dead claim: give up - retract the orphaned inbox
        // copy if the worker never picked it up and clear the claim
        // so the escalated record carries no dangling task
        try {
          fs.unlinkSync(HANDS_QUEUE + '/inbox/' + tid + '.json');
        } catch (e) {}
        delete run.scorer_pending;
        trace(run, 'escalate', { reason: 'scorer_failed',
          task: tid, stale: true });
        escalateRun(run, 'scorer_failed', { task: tid, stale: true });
        return 'escalated';
      }
      try {
        fs.unlinkSync(HANDS_QUEUE + '/inbox/' + tid + '.json');
      } catch (e) {}
      run.scorer_retries = retries + 1;
      delete run.scorer_pending;
      trace(run, 'score-stale-clear', { task: tid });
      // falls through to arming a fresh task below
    }
  }
  // arm a new pangram task for the current working text
  const w = wordsOf(run.working_text);
  if (w < PANGRAM_MIN_WORDS) {
    trace(run, 'escalate', { reason: 'scorer_inconclusive',
      words: w });
    escalateRun(run, 'scorer_inconclusive', { words: w });
    return 'escalated';
  }
  const haveQueue = ['inbox', 'done', 'failed'].every((d) =>
    fs.existsSync(HANDS_QUEUE + '/' + d));
  if (!haveQueue) {
    // missing bind mount: stub scores this run from here on, with
    // the fallback on the record so later cells don't re-probe the
    // mount every tick
    run.scorer_fallback = true;
    trace(run, 'scorer-fallback-stub',
      { reason: 'queue_unavailable' });
    const s = stubScore(run.working_text, run.iteration);
    recordScore(run, s);
    trace(run, 'score', { via: 'stub', score: s.score,
      label: s.label, stage: cellStage(run) });
    run.state = 'decide';
    return 'scored-stub-fallback';
  }
  const cost = Math.ceil(w / 100);
  const seq = Number(run.score_seq || 0);
  const tid = 'pangram-' + id + '-' + seq;
  const outcome = withLock('pangram-credits', 15000, () => {
    const c = loadCredits();
    if (!c.charged || typeof c.charged !== 'object') c.charged = {};
    // crash window between the inbox rename and the run write: a
    // tick that dies there leaves the run WITHOUT scorer_pending
    // while the charge already landed. The task id is deterministic
    // (run id + score_seq), so the recovering re-arm arrives with
    // the SAME tid - the per-task 'charged' ledger (written
    // atomically with est_spent) makes the retry re-enqueue the task
    // file WITHOUT spending the credit a second time
    const already = Number(c.charged[tid]) || 0;
    if (!already && c.est_spent + cost > HUMANIZER_DAILY) {
      return 'credit_cap';
    }
    if (!already) {
      c.est_spent += cost;
      c.charged[tid] = cost;
      writeJsonAtomic(PANGRAM_CREDITS, c);
    }
    // idempotent re-arm: an inbox file that survived the crash IS
    // the task we want; only (re)write when it is missing
    const ip = HANDS_QUEUE + '/inbox/' + tid + '.json';
    if (!fs.existsSync(ip)) {
      // same dot-tmp + rename the pangram warn-gate enqueue uses:
      // the worker polls inbox/ and a torn payload must never be
      // read as a task
      const tmp = HANDS_QUEUE + '/inbox/.' + tid + '.tmp-' +
        Date.now().toString(36) +
        Math.random().toString(36).slice(2, 6);
      fs.writeFileSync(tmp, JSON.stringify({
        recipe: 'pangram_check',
        params: {
          text: String(run.working_text),
          // first ~60 chars of the whitespace-collapsed text: the
          // recipe matches the newest history row whose innerText
          // starts with the checked text's head
          snippet: Array.from(String(run.working_text)
            .replace(/\s+/g, ' ').trim()).slice(0, 60).join('').trim()
        }
      }, null, 2));
      fs.renameSync(tmp, ip);
    }
    return 'enqueued';
  });
  if (outcome === 'credit_cap') {
    trace(run, 'escalate', { reason: 'credit_cap',
      words: w, cost: cost });
    log({ run: id, action: 'humanizer-credit-cap',
      words: w, cost: cost });
    escalateRun(run, 'credit_cap');
    return 'escalated';
  }
  run.score_seq = seq + 1;
  run.credits_used = Number(run.credits_used || 0) + cost;
  run.scorer_pending = { task: tid, words: w, cost: cost,
    at: new Date().toISOString() };
  trace(run, 'score-enqueue', { task: tid, words: w, cost: cost,
    stage: cellStage(run) });
  return 'enqueued';
};

// rewriting stage: claim -> async stage call -> settle. The claim is
// the pangram poll's claim-first discipline: the pending marker
// lands under the run lock BEFORE the call, so an overlapping tick
// can never double-invoke the partner on the same cell
const rewriteStep = async (id) => {
  const nonce = Date.now().toString(36) + '-' +
    Math.random().toString(36).slice(2, 8);
  let stage = null;
  let run0 = null;
  try {
    withLock('hrun-' + id, 15000, () => {
      run0 = updateRun(id, (cur) => {
        stage = cur.stages[cur.iteration % cur.stages.length];
        cur.rewrite_pending = { nonce: nonce, stage: stage,
          at: new Date().toISOString() };
        trace(cur, 'rewrite-claim', { stage: stage,
          iteration: cur.iteration });
      }, (cur) => !!(cur && cur.state === 'rewriting' &&
        !cur.rewrite_pending && cur.stages && cur.stages.length));
    });
  } catch (e) {
    run0 = null;
  }
  if (!run0) return 'busy';
  const result = await callStage(stage, loadRun(id) || run0);
  let settled = null;
  try {
    withLock('hrun-' + id, 15000, () => {
      settled = updateRun(id, (cur) => {
        delete cur.rewrite_pending;
        if (result.unavailable) {
          // declared stage with no configured endpoint: the cell is
          // recorded 'unavailable' in the score ledger so the matrix
          // still shows it, then the run escalates - no fake call,
          // no silent skip
          recordScore(cur, { score: null, label: 'unavailable',
            confidence: null, via: 'none',
            words: wordsOf(cur.working_text),
            at: new Date().toISOString() });
          trace(cur, 'escalate',
            { reason: 'stage_unavailable', stage: stage });
          escalateRun(cur, 'stage_unavailable',
            { stage: stage });
          return;
        }
        if (!result.ok) {
          cur.previous_attempts =
            (cur.previous_attempts || []).concat([{
              iteration: cur.iteration, stage: stage,
              failed: true,
              error: cap(result.error || 'stage failed', 150) }])
              .slice(-10);
          trace(cur, 'escalate', { reason: 'partner_failed',
            stage: stage, error: cap(result.error, 150) });
          escalateRun(cur, 'partner_failed', { stage: stage });
          return;
        }
        cur.working_text = result.rewritten_text;
        cur.cell_stage = stage;
        cur.iteration = Number(cur.iteration || 0) + 1;
        cur.last_edits = result.edits || [];
        trace(cur, 'rewrite', { stage: stage,
          iteration: cur.iteration,
          edits: (result.edits || []).length });
        cur.state = 'rescoring';
      }, (cur) => !!(cur && cur.rewrite_pending &&
        cur.rewrite_pending.nonce === nonce));
    });
  } catch (e) {
    settled = null;
    log({ run: id, action: 'rewrite-settle-failed',
      error: String((e && e.message) || e).slice(0, 150) });
  }
  if (!settled) {
    log({ run: id, action: 'rewrite-settle-vetoed', stage: stage });
    return 'vetoed';
  }
  return 'rewrote';
};

// one tick = one step per live run ---------------------------------------
const stepRun = async (id) => {
  const head = loadRun(id);
  if (!head) return 'gone';
  if (head.state === 'done' || head.state === 'escalated') {
    return 'terminal';
  }
  // a rewrite_pending that outlives REWRITE_STALE_MS is a crashed
  // tick: clear it under the lock so the stage gets re-claimed
  if (head.rewrite_pending) {
    const at = Date.parse(head.rewrite_pending.at || '');
    if (!Number.isFinite(at) || Date.now() - at > REWRITE_STALE_MS) {
      try {
        withLock('hrun-' + id, 15000, () => {
          updateRun(id, (cur) => {
            delete cur.rewrite_pending;
            trace(cur, 'rewrite-stale-clear', {});
          }, (cur) => !!(cur && cur.rewrite_pending &&
            cur.rewrite_pending.nonce ===
              head.rewrite_pending.nonce));
        });
      } catch (e) { return 'busy'; }
    } else {
      return 'pending-rewrite';
    }
  }
  const state = head.state;
  if (state === 'rewriting') {
    return await rewriteStep(id);
  }
  let out = 'idle';
  try {
    withLock('hrun-' + id, 15000, () => {
      updateRun(id, (cur) => {
        if (cur.state === 'scoring' || cur.state === 'rescoring') {
          out = scoreStep(cur, id);
        } else if (cur.state === 'decide') {
          out = decideStep(cur);
        } else {
          out = 'unknown-state';
          trace(cur, 'unknown-state', { state: cur.state });
        }
      }, (cur) => !!(cur && cur.state === state));
    });
  } catch (e) {
    log({ run: id, action: 'run-step-failed',
      error: String((e && e.message) || e).slice(0, 150) });
    return 'error';
  }
  return out;
};

// seeding: every tick scans the fixture corpus and creates missing
// runs for the enabled chains. Idempotent by contract - an existing
// run file (in ANY state) is never re-seeded, so an operator can
// replay a tier by deleting its run files only
const chainStages = (name) => {
  if (name === 'baseline') return [];
  if (name === 'editor') return ['editor'];
  return name.split('+').map((s) => s.trim()).filter(Boolean);
};
const seedScan = () => {
  const tiers = listDir(FIXTURES);
  if (!tiers) {
    log({ action: 'seed-skip', reason: 'fixtures dir missing',
      dir: FIXTURES });
    return 0;
  }
  const chains = CHAINS.split(',')
    .map((s) => s.trim()).filter(Boolean);
  let seeded = 0;
  for (const tier of tiers.sort()) {
    if (!/^[A-Za-z0-9_-]+$/.test(tier)) continue;
    const td = FIXTURES + '/' + tier;
    try {
      if (!fs.statSync(td).isDirectory()) continue;
    } catch (e) { continue; }
    const files = listDir(td) || [];
    for (const f of files.sort()) {
      const m = /^([a-z]{2})\.txt$/.exec(f);
      if (!m) continue;
      const lang = m[1];
      let text = null;
      try {
        text = fs.readFileSync(td + '/' + f, 'utf8');
      } catch (e) { continue; }
      for (const cn of chains) {
        // '+'-joined chains are legal in CHAINS but not in a run
        // filename - the tick's file filter only steps
        // [A-Za-z0-9_-] ids, so fold everything else to '-'
        const id = (cn + '__' + tier + '-' + lang)
          .replace(/[^A-Za-z0-9_-]+/g, '-');
        if (fs.existsSync(runPath(id))) continue;
        const stages = chainStages(cn);
        const run = {
          run_id: id,
          fixture: tier + '/' + lang,
          tier: tier,
          lang: lang,
          chain: cn,
          stages: stages,
          state: 'scoring',
          iteration: 0,
          cell_stage: 'input',
          text: text,
          working_text: text,
          mode: 'rewrite',
          best: null,
          last_score: null,
          last_edits: [],
          scorer_pending: null,
          rewrite_pending: null,
          previous_attempts: [],
          protected_terms: [],
          persona_context: '',
          credits_used: 0,
          score_seq: 0,
          scorer_retries: 0,
          scorer_fallback: false,
          outcome: null,
          escalation: null,
          trace: [],
          seeded_at: new Date().toISOString(),
          updated_at: new Date().toISOString()
        };
        trace(run, 'seeded', { chain: cn, stages: stages,
          words: wordsOf(text) });
        try {
          writeJsonAtomic(runPath(id), run);
          seeded++;
        } catch (e) {
          log({ action: 'seed-write-failed', run: id,
            error: String((e && e.message) || e).slice(0, 150) });
        }
      }
    }
  }
  if (seeded) log({ action: 'seeded', count: seeded });
  return seeded;
};
// the existsSync -> writeJsonAtomic gap in seedScan is a seed race:
// two overlapping ticks could both see a run file missing and the
// later writer would wipe the earlier one's progress. The whole
// scan runs under the 'humanizer-seed' lock so only one tick seeds
// at a time; a busy lock means another tick is mid-seed - its files
// are already visible to the step loop, so we report 0 seeded
const seedRuns = () => {
  try {
    return withLock('humanizer-seed', 30000, seedScan);
  } catch (e) {
    if (!e || !e.lockBusy) {
      try {
        log({ action: 'seed-failed',
          error: String((e && e.message) || e).slice(0, 150) });
      } catch (e2) {}
    }
    return 0;
  }
};

const summary = { seeded: 0, stepped: 0, by_step: {} };
summary.seeded = seedRuns();
const names = listDir(RUNS) || [];
for (const fname of names.sort()) {
  const m = /^([A-Za-z0-9_-]+)\.json$/.exec(fname);
  if (!m) continue;
  const id = m[1];
  try {
    const r = await stepRun(id);
    summary.stepped++;
    summary.by_step[r] = (summary.by_step[r] || 0) + 1;
  } catch (e) {
    // per-run containment: one malformed record must not abort the
    // tick
    log({ run: id, action: 'run-step-error',
      error: String((e && e.message) || e).slice(0, 150) });
    summary.by_step.error = (summary.by_step.error || 0) + 1;
  }
}
return [{ json: { ok: true, scorer: SCORER, partner: PARTNER,
  threshold: THRESHOLD, ...summary } }];
